package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The workspace's annual late-interest rate: the stored {@code late_interest_rate} setting, a
 * percentage such as 12. With no rate set no late interest is charged, so the rate is 0. A region can
 * have a legal maximum annual rate, the {@code region_max_interest_<region>} setting: its clients are
 * charged late interest at no more than it (invoices read the cap themselves, see Invoice).
 */
@Service
public class LateInterestRate {

    static final String LATE_INTEREST_RATE = "late_interest_rate";

    /** The prefix of the setting holding a region's legal maximum rate, followed by the region (region_max_interest_NY). */
    public static final String REGION_MAX_INTEREST = "region_max_interest_";

    private final JdbcTemplate jdbc;

    public LateInterestRate(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public BigDecimal percent() {
        List<String> rate = jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?",
                String.class, LATE_INTEREST_RATE);
        return rate.isEmpty() ? BigDecimal.ZERO : new BigDecimal(rate.get(0));
    }

    /** Every region's legal maximum annual rate, by region. */
    public Map<String, BigDecimal> regionMaximums() {
        Map<String, BigDecimal> caps = new TreeMap<>();
        jdbc.queryForList("SELECT name, setting_value FROM app_setting WHERE name LIKE ? ORDER BY name", REGION_MAX_INTEREST + "%")
                .forEach(r -> caps.put(((String) r.get("NAME")).substring(REGION_MAX_INTEREST.length()),
                        new BigDecimal((String) r.get("SETTING_VALUE"))));
        return caps;
    }

    /** Records the region's legal maximum annual rate. */
    public void setRegionMaximum(String region, BigDecimal percent) {
        jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)", REGION_MAX_INTEREST + region,
                percent.toPlainString());
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.clients.Currency;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The workspace's exchange rates: the US dollars one unit of each currency is worth, stored as the
 * {@code usd_per_<code>} settings. A US dollar is worth one; a currency with no rate set is taken
 * at par. Dated rates (the {@code fx_rate} table) take over from their date on: something converted on
 * a date uses the latest dated rate on or before it, or the standing rate before any. Invoices read
 * their client's rates themselves (see Invoice).
 */
@Service
public class ExchangeRates {

    /** The prefix of the setting holding a currency's rate, followed by its code (usd_per_EUR). */
    public static final String USD_PER = "usd_per_";

    private final JdbcTemplate jdbc;

    public ExchangeRates(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every rate set, by currency code. */
    public Map<String, BigDecimal> all() {
        Map<String, BigDecimal> rates = new LinkedHashMap<>();
        jdbc.queryForList("SELECT name, setting_value FROM app_setting WHERE name LIKE ? ORDER BY name", USD_PER + "%")
                .forEach(r -> rates.put(((String) r.get("NAME")).substring(USD_PER.length()),
                        new BigDecimal((String) r.get("SETTING_VALUE"))));
        return rates;
    }

    /** A dated rate: from the date on, the US dollars one unit of the currency is worth. */
    public record Dated(LocalDate from, Currency currency, BigDecimal usdPer) {
    }

    /** Every dated rate, by date then currency. */
    public List<Dated> dated() {
        return jdbc.query("SELECT from_date, currency, usd_per FROM fx_rate ORDER BY from_date, currency, id",
                (rs, n) -> new Dated(rs.getDate(1).toLocalDate(), Currency.of(rs.getString(2)), rs.getBigDecimal(3)));
    }

    /** Adds a dated rate. */
    public void addDated(LocalDate from, Currency currency, BigDecimal usdPer) {
        jdbc.update("INSERT INTO fx_rate (from_date, currency, usd_per) VALUES (?, ?, ?)", Date.valueOf(from),
                currency.name(), usdPer);
    }

    /**
     * The US dollars one unit of the currency is worth on the date: the latest dated rate on or before
     * it, otherwise the standing rate (see {@link #usdPer(Currency)}).
     */
    public BigDecimal usdPer(Currency currency, LocalDate on) {
        if (currency == Currency.USD) {
            return BigDecimal.ONE;
        }
        return jdbc.queryForList("SELECT usd_per FROM fx_rate WHERE currency = ? AND from_date <= ? ORDER BY from_date DESC, id DESC LIMIT 1",
                BigDecimal.class, currency.name(), Date.valueOf(on)).stream().findFirst().orElseGet(() -> usdPer(currency));
    }

    /** The US dollars one unit of the currency is worth: one for the dollar or a currency with no rate set. */
    public BigDecimal usdPer(Currency currency) {
        if (currency == Currency.USD) {
            return BigDecimal.ONE;
        }
        return jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?", String.class, USD_PER + currency.name())
                .stream().findFirst().map(v -> new BigDecimal(v.trim())).orElse(BigDecimal.ONE);
    }

    /**
     * The amount paid in one currency converted into another through US dollars: amount x (dollars per
     * unit paid) / (dollars per unit of the other), at the rates in force on the date, worked out exactly
     * and rounded down to the other's step, so the client is never credited more than was received.
     */
    public BigDecimal convert(BigDecimal amount, Currency from, Currency to, LocalDate on) {
        if (from == to) {
            return amount.setScale(to.scale());
        }
        return to.divideDownToStep(amount.multiply(usdPer(from, on)), usdPer(to, on));
    }
}
    private final PaymentRepository payments;
    private final EntityManager entityManager;
    private final ExchangeRates exchangeRates;

    private final CardSurcharge cardSurcharge;

    private final PriceList priceList;

    private final Today today;

    private final LateInterestRate lateInterestRate;

    private final VolumeDiscounts volumeDiscounts;

    public TestSupportController(Audit audit, JdbcTemplate jdbc, InvoiceRepository invoices, TaxRate taxRate,
            PaymentRepository payments, EntityManager entityManager, ExchangeRates exchangeRates,
            CardSurcharge cardSurcharge, PriceList priceList, Today today, LateInterestRate lateInterestRate,
            VolumeDiscounts volumeDiscounts) {
        this.volumeDiscounts = volumeDiscounts;
        this.lateInterestRate = lateInterestRate;
        this.today = today;
        this.priceList = priceList;
        this.cardSurcharge = cardSurcharge;
        this.exchangeRates = exchangeRates;
        this.payments = payments;
        this.entityManager = entityManager;
        this.audit = audit;
        this.jdbc = jdbc;
        this.invoices = invoices;
        this.taxRate = taxRate;
    }

    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
    @PostMapping("/reset")
    @Transactional
    public void reset() {
        audit.clear();
        jdbc.execute("DELETE FROM app_setting");
        jdbc.execute("DELETE FROM fx_rate");
        jdbc.execute("DELETE FROM volume_discount");
        jdbc.execute("DELETE FROM tax_rate_change");
        jdbc.execute("DELETE FROM payment_allocation");
        jdbc.execute("DELETE FROM client_rate");
        jdbc.execute("DELETE FROM price_list_rate");
        for (String table : List.of("payment", "invoice_line", "invoice", "client")) {
            jdbc.execute("DELETE FROM " + table);
            jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH 1");
        }
    }

    /**
     * Insert the fixture a spec needs; the payload shape evolves with the schema. Store every field
     * given, or refuse with HTTP 400 naming it — never ignore one silently (AGENTS.md §4.2).
     */
    @PostMapping("/seed")
    @Transactional
    public void seed(@RequestBody Map<String, Object> fixture) {
        for (String key : fixture.keySet()) {
            if (!FIXTURE_KEYS.contains(key)) {
                throw refuse("unsupported fixture key: " + key);
            }
        }
        if (fixture.get("asOf") != null) {
            LocalDate asOf = date(fixture.get("asOf"), "asOf");
            jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)", Today.AS_OF, asOf.toString());
        }
        if (fixture.get("settings") != null) {
            if (!(fixture.get("settings") instanceof Map<?, ?> settings)) {
                throw refuse("settings must be an object");
            }
            @SuppressWarnings("unchecked")
            Map<String, Object> values = (Map<String, Object>) settings;
            only(values, SETTINGS_FIELDS, "settings");
            if (values.get("taxRate") != null) {
                BigDecimal rate = percent(values.get("taxRate"), "settings.taxRate");
                jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)", TaxRate.TAX_RATE,
                        rate.toPlainString());
            }
            if (values.get("lateInterestRate") != null) {
                BigDecimal rate = percent(values.get("lateInterestRate"), "settings.lateInterestRate");
                jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)",
                        LateInterestRate.LATE_INTEREST_RATE, rate.toPlainString());
            }
            if (values.get("minimumCharge") != null) {
                BigDecimal minimum = money(values.get("minimumCharge"), "settings.minimumCharge");
                jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)",
                        MINIMUM_CHARGE, minimum.toPlainString());
            }
            if (values.get("cardSurchargePct") != null) {
                BigDecimal rate = percent(values.get("cardSurchargePct"), "settings.cardSurchargePct");
                jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)",
                        CardSurcharge.CARD_SURCHARGE_PCT, rate.toPlainString());
            }
            if (values.get("usdPer") != null) {
                if (!(values.get("usdPer") instanceof Map<?, ?> rates)) {
                    throw refuse("settings.usdPer must be an object of rates by currency code");
                }
                for (Map.Entry<?, ?> e : rates.entrySet()) {
                    String code = e.getKey().toString();
                    if (Currency.of(code) == null) {
                        throw refuse("unsupported currency in settings.usdPer: " + code);
                    }
                    BigDecimal usdPer;
                    try {
                        usdPer = new BigDecimal(String.valueOf(e.getValue()));
                    } catch (NumberFormatException ex) {
                        throw refuse("settings.usdPer." + code + " must be a number, not " + e.getValue());
                    }
                    if (usdPer.signum() <= 0) {
                        throw refuse("settings.usdPer." + code + " must be more than zero, not " + e.getValue());
                    }
                    jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)",
                            ExchangeRates.USD_PER + code, usdPer.toPlainString());
                }
            }
            if (values.get("regionTaxRates") != null) {
                if (!(values.get("regionTaxRates") instanceof Map<?, ?> rates)) {
                    throw refuse("settings.regionTaxRates must be an object of percentages by region");
                }
                for (Map.Entry<?, ?> e : rates.entrySet()) {
                    String region = e.getKey().toString();
                    if (region.isBlank() || e.getValue() == null) {
                        throw refuse("settings.regionTaxRates needs a region and a rate, not " + region + ": " + e.getValue());
                    }
                    BigDecimal rate;
                    try {
                        rate = new BigDecimal(String.valueOf(e.getValue()));
                    } catch (NumberFormatException ex) {
                        throw refuse("settings.regionTaxRates." + region + " must be a number, not " + e.getValue());
                    }
                    if (rate.signum() < 0 || rate.compareTo(BigDecimal.valueOf(100)) > 0) {
                        throw refuse("settings.regionTaxRates." + region + " must be from 0 to 100, not " + e.getValue());
